#!/usr/bin/env python3
"""
Round 97b tiles patch (28 September 2026): fixes for the five scripts that
failed in the refresh run of 28 September.

  military.py      main() named ucdp but the function was missing (NameError,
                   so no military part ran). ucdp() written again: UCDP GED's
                   newest global release and this year's candidate files, from
                   the links on ucdp.uu.se/downloads; every field kept in the
                   256 pieces of military/ucdp/, tiles/mil_conflicts.pmtiles
                   with id, date, kind and deaths.
  mangroves.py     rasterio will not use "max" on a plain read; each square is
                   now warped onto the grid with "max" (WarpedVRT).
  gsn_rankings.py  every sheet was "skipped": the workbook is read in full
                   (not read_only, which trusts a sheet's stated size), a
                   place name in a row is no longer taken for the header, the
                   name column is found by its contents if no header names it,
                   and the first rows of each sheet are printed.
  wasteatlas.py    the site's data.xml would not parse; markers are read one
                   by one when the whole file does not.
  aqueduct.py      the data lake answers 403 and the Data API has no geojson
                   download (404); its csv download of the whole table is used.

Whole files, written only where they differ. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/military.py': '', 'scripts/mangroves.py': '', 'scripts/gsn_rankings.py': '', 'scripts/wasteatlas.py': '', 'scripts/aqueduct.py': ''}

changed = []
for path, b64 in FILES.items():
    p = pathlib.Path(path)
    new = base64.b64decode(b64)
    if not p.parent.exists():
        raise SystemExit(f"round97b: {p.parent} not found; run from the culprits-tiles-more root")
    if p.exists() and p.read_bytes() == new:
        continue
    p.write_bytes(new)
    changed.append(path)
print("round97b: " + (", ".join(changed) if changed else "nothing to change (already applied)"))
